SELECT rl.reservation_lane_id,r.reservation_id,l.lane_number,r.status,rl.usage_status,u.actual_start_time,u.actual_end_time FROM RESERVATION_LANE rl JOIN RESERVATION r ON r.reservation_id=rl.reservation_id JOIN LANE l ON l.lane_id=rl.lane_id LEFT JOIN USAGE u ON u.reservation_lane_id=rl.reservation_lane_id ORDER BY r.reservation_id,l.lane_number;
SELECT l.lane_id,l.status,COUNT(u.usage_id) active_count FROM LANE l LEFT JOIN RESERVATION_LANE rl ON rl.lane_id=l.lane_id LEFT JOIN USAGE u ON u.reservation_lane_id=rl.reservation_lane_id AND u.actual_end_time IS NULL GROUP BY l.lane_id,l.status HAVING (l.status='IN_USE' AND COUNT(u.usage_id)<>1) OR (l.status<>'IN_USE' AND COUNT(u.usage_id)>0);
